---RemoveCardById
---根据传入id移除身上的卡牌
---@param id number
function CardComponent:RemoveCardById(id)
    id = checkNumber(id)
    --移除编队
    local cardDojo = self:GetCardById(id)
    if not isTable(cardDojo) then
        return
    end
    ---@type TeamComponent
    local teamComp = GameUtils:GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
    --移除编队
    --图型卡
    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local equipDojo = nil
    for i = 1, Constants.CardEquipmentNo do
        ---检测6个图芯卡位置清除playerid的信息
        local key = string.format('tarot%s', tostring(i))
        local playerTarotId = cardDojo[key]
        if checkNumber(playerTarotId) > 0 then
            ---当前要移除的卡牌身上有图芯卡删除对照关系
            equipDojo = equipComp:GetEquipById(playerTarotId)
            if not isNull(equipDojo) then
                equipDojo.playerCardId = 0
            end
        end
    end
    ---然后再删除卡牌
    for i = 1, #self.cards do
        if checkNumber(self.cards[i].id) == id then
            table.remove(self.cards, i) ---删除指定位置的卡牌
            self._id2dojo[tostring(id)] = nil ---删除内部集合
            break
        end
    end
end



