    end
end

---RemoveAllEquipById
---移除卡牌所有的装备
---@param playerCardId number
---@return CardDojo
function CardComponent:RemoveAllEquipById(playerCardId)
    local cardDojo = self:GetCardById(playerCardId)
    ---@type ECSEntity
    local entity = self.entity
    ---@type EquipmentComponent
    local equipComp = entity:GetComp(ECSComponentType.Constants.EquipmentComponent)
    for i = 1, Constants.CardEquipmentNo do
        local key = string.format('equipment%s', tostring(i))
        local oldPlayerEquipId = checkNumber(cardDojo[key])
        if oldPlayerEquipId > 0 then
            equipComp:RemoveCardOnEquip(playerCardId, oldPlayerEquipId)
        end
    end

    local equipmentCore = checkNumber(cardDojo.equipmentCore)
    if equipmentCore > 0 then
        equipComp:RemoveCardOnEquipCore(playerCardId, equipmentCore)
    end

    return cardDojo
end

---AddAllEquipByIdList
---@param playerCardId number
---@param equipIdList table
function CardComponent:AddEquipData(playerCardId, equipIdList, equipmentCore)
    ---@type ECSEntity
    local entity = self.entity
    ---@type EquipmentComponent
    local equipComp = entity:GetComp(ECSComponentType.Constants.EquipmentComponent)
    local cardDojo = self:GetCardById(playerCardId)
    if equipIdList ~= nil then
        for i = 1, Constants.CardEquipmentNo do
            local playerEquipId = checkNumber(equipIdList[i])
            local key = EquipUtils.GetEquipIdKeyByPart(i)
            local oldPlayerEquipId = checkNumber(cardDojo[key])
            --- 该卡牌指定位置拥有 装备 并且 要替换的装备id 为0 则移除该装备身上的卡牌id
            if oldPlayerEquipId > 0 and playerEquipId == 0 then
                equipComp:RemoveCardOnEquip(playerCardId, oldPlayerEquipId)
            end
            if playerEquipId > 0 then
                equipComp:AddCardOnEquip(playerCardId, playerEquipId, i)
            end
        end
    end

    if equipmentCore ~= nil then
        local oldEquipmentCore = checkNumber(cardDojo.equipmentCore)
        if oldEquipmentCore > 0 and equipmentCore == 0 then
            equipComp:RemoveCardOnEquipCore(playerCardId, oldEquipmentCore)
        end

        if equipmentCore > 0 then
            equipComp:AddCardOnEquipCore(playerCardId, equipmentCore)
        end
    end

    return cardDojo
end

