---AddCardDojo
---添加卡牌
---@param cardDojo CardDojo
function CardComponent:AddCardDojo(cardDojo)
    if not isTable(cardDojo) then
        return
    end
    --角色解锁的小红点
    PhoneUtils.CheckRole(cardDojo.cardId)

    table.insert(self.cards, cardDojo)
    local playerCardId = tostring(cardDojo.id) 
    self._id2dojo[playerCardId] = cardDojo ---记录更新内部集合
    self._unlockCardId[checkInt(cardDojo.cardId)] = playerCardId
    --local isChangeRating = self:UpdateRatingIdByStar(cardDojo.star)

    local cardVo = cardConfMgr:GetCardByRefId(cardDojo.cardId)
    self._catTypeUnlockedMap[checkInt(cardVo.catType)] = true

    -- 图鉴收集 增加已收集 卡牌/猫种
    ---@type IllustratedHandbookComponent
    local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
    illustratedHandbookComp:CheckHandbookStorage(Constants.HandbookCollectionType.ROLE, cardDojo.cardId)
    illustratedHandbookComp:CheckHandbookStorage(Constants.HandbookCollectionType.CAT, cardVo.catType)
    illustratedHandbookComp:CheckHandbookRoleRedPoint()
    illustratedHandbookComp:CheckHandbookCatRedPoint()
    -- 卡牌收集 增加已收集 UR数
    illustratedHandbookComp:CheckAdditionStorage(Constants.CardCollectionType.UR_NUM, cardDojo)
    illustratedHandbookComp:CheckAdditionUrNumRedPoint()

    self:SetNewByCardId(cardDojo.cardId, true)
    ----小红点本地生成卡牌对照
    -----@type RedPointMgrComponent
    --local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)
    --redPointCom:AddGoodsMappingCard(cardDojo)
    
    -- 获得了一张新卡牌
    Events.Broadcast(Constants.EventNames.GetNewCard, checkNumber(playerCardId), checkNumber(cardDojo.cardId))
    return false
end

---UpdateCardDojo
---@param playerCardId table 玩家卡牌id
---@param jsonData table     玩家卡牌数据
function CardComponent:UpdateCardDojo(playerCardId, jsonData)
    -- print(playerCardId, table.toString(jsonData))
    ---@type CardDojo
    local cardDojo = self:GetCardById(playerCardId)
    cardDojo = cardDojo:Fill(jsonData)
    local isChangeRating = false

    -- 卡牌收集 增加已收集 提升星级
    if jsonData.star ~= nil then
        ---@type IllustratedHandbookComponent
        local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
        illustratedHandbookComp:CheckAdditionStorage(Constants.CardCollectionType.STAR, cardDojo)
        illustratedHandbookComp:CheckAdditionStarRedPoint()
    end

    -- 卡牌收集 增加已收集 进阶到UR
    if jsonData.advanceLevel ~= nil then
        ---@type IllustratedHandbookComponent
        local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
        illustratedHandbookComp:CheckAdditionStorage(Constants.CardCollectionType.UR_NUM, cardDojo)
        illustratedHandbookComp:CheckAdditionUrNumRedPoint()
    end

    -- 卡牌收集 增加已收集 技能升级次数
    if jsonData.finalSkillLevel ~= nil or jsonData.awakeningLevel ~= nil then
        ---@type IllustratedHandbookComponent
        local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
        illustratedHandbookComp:CheckAdditionStorage(Constants.CardCollectionType.SKILL, cardDojo)
        illustratedHandbookComp:CheckAdditionSkillRedPoint()
    end

    return cardDojo, isChangeRating
end

