function CardComponent:GetCatHouseHandbookAttrId2Num()
    if next(self._catHouseHandbookAttrId2Num) ~= nil then
        return self._catHouseHandbookAttrId2Num
    end

    return self:InitCatHouseHandbookAttrId2Num_()
end

--- InitCatHouseHandbookAttrId2Num_
--- 外部掉用 UpdateCatHouseHandbookAttrId2Num
function CardComponent:InitCatHouseHandbookAttrId2Num_()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo = playerComponent:GetPlayerDojo()
    self._catHouseHandbookAttrId2Num = CardUtils.CalcCatHouseHandbookAttrId2Num(playerDojo.unlockGenes)
    return self._catHouseHandbookAttrId2Num
end

function CardComponent:UpdateCatHouseHandbookAttrId2Num(geneId)
    --- 没有实际调用过 不处理 
    if next(self._catHouseHandbookAttrId2Num) == nil then
        return
    end
    local checkNumber       = checkNumber
    local attrId2Num        = self._catHouseHandbookAttrId2Num
    ---@type CatHouseCatDataVo
    local catHouseCatDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
    local variationKindList = catHouseCatDataVo.variationKindList
    if variationKindList == nil then return end
    local variationNumList  = catHouseCatDataVo.variationNumList
    for i, additionId in pairs(variationKindList) do
        local num  = attrId2Num[additionId] or 0
        attrId2Num[additionId] = num + checkNumber(variationNumList[i])
    end
end

function CardComponent:FixCardLevel(oldPlayerLevel, newPlayerLevel)
    ---@type CardProgressionUtils
    local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
    ---1. 检查是否需要修正卡牌等级 
    local oldCardLimitLv = CardProgressionUtils.GetCardLevelLimit(oldPlayerLevel)
    local newCardLimitLv = CardProgressionUtils.GetCardLevelLimit(newPlayerLevel)
    if newCardLimitLv > 0 and oldCardLimitLv > 0 and newCardLimitLv <= oldCardLimitLv then
        return
    end
    local checkNumber           = checkNumber
    local BinarySearchLeftBound = BinarySearchLeftBound
    ---2. 修正卡牌等级
    ---@type CardDojo[]
    local cardDojos = self:GetAllCardTable()
    for i, cardDojo in ipairs(cardDojos) do
        local advanceLevel = cardDojo.advanceLevel
        local maxLevel     = cardConfMgr:GetCardMaxLevel(advanceLevel)
        local targetLevel  = math.min(newCardLimitLv, maxLevel)
        local cardLevel    = checkNumber(cardDojo.cardLevel)
        if cardLevel < targetLevel then
            local cardExp  = checkNumber(cardDojo.cardExp)
            ---@type CardVo
            local cardVo   = cardConfMgr:GetCardByRefId(cardDojo.cardId)
            local initRare = cardVo.rare
            local level    = BinarySearchLeftBound(cardLevel, targetLevel, cardExp, function(middle)
                return cardConfMgr:GetCardExp(middle, initRare, targetLevel).totalExp
            end)
            cardDojo:UpdateCardLevel(level)
            
        end
    end
end

