---GetNewByCardId
---通关卡牌id获取新增卡牌标识
---@param cardId integer 卡牌配表id
function CardComponent:GetNewByCardId(cardId)
    if self._configId2New[checkNumber(cardId)] == nil then
        self._configId2New[checkNumber(cardId)] = checkNumber(CfUtils.GetLocalData(string.format(CardNewKey, cardId), 0)) == 1
    end
    return self._configId2New[checkNumber(cardId)] == true

end
---GetNewByCardId
---设置新增卡牌标识
---@param cardId integer 卡牌配表id
---@param isNew integer 新增卡牌标识
function CardComponent:SetNewByCardId(cardId, isNew)
    local oldNew = self:GetNewByCardId(cardId)
    if oldNew ~= isNew then
        if isNew then
            CfUtils.WriteLocalData(string.format(CardNewKey, cardId), 1)
        else
            CfUtils.WriteLocalData(string.format(CardNewKey, cardId), 0)
        end

        self._configId2New[checkNumber(cardId)] = isNew
    end

end
--- func desc 获取SSR拥有的总数
function CardComponent:GetSRRCount()
    ---@type CardVo[]
    local cardVos = CfUtils.GetWholeVo(AutoIds.IdSetting28, "CardVo")
    local SSR = Constants.RareType.SSR
    local count = 0 
    for k, v in ipairs(cardVos) do
         if v.rare == SSR then
            local playerCardId = self:GetIdByCardId(v.roleId)
            if checkInt(playerCardId) > 0 then
                count = count + 1
            end
         end
    end
    return count
end
---更新卡牌合成红点
function CardComponent:UpdateCardFusionRedPoint()
    local backpackComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local totalData = backpackComponent:GetGoodsByTypeId(Constants.IDType.GoodsSameCard)
    for _, v in ipairs(totalData) do
        if checkInt(v.num) >= checkInt(v.vo.needNum) and not self:IsHasCard(v.vo.cardId) then
            GameUtils.SetRedPointNum(Constants.RedPointConst.ConvertExchangeCard, 1)
            return
        end
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.ConvertExchangeCard, 0)
end

---更新卡牌粉尘合成红点
function CardComponent:UpdateCardDustRedPoint()
    local backpackComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local totalData = backpackComponent:GetGoodsByTypeId(Constants.IDType.GoodsSameCardDust)
    for _, v in ipairs(totalData) do
        if checkInt(v.num) >= checkInt(v.vo.needNum) and not self:IsHasCard(v.vo.cardId) then
            GameUtils.SetRedPointNum(Constants.RedPointConst.ConvertExchangeCardDust, 1)
            return
        end
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.ConvertExchangeCardDust, 0)
end
return CardComponent